        {
            for (int t = 0; t < steps; t++) {
                double *src = (t % 2 == 0) ? u : v;
                double *dst = (t % 2 == 0) ? v : u;
                #pragma omp for schedule(static)
                for (int i = 1; i < n - 1; i++) {
